body.zh:
// 无依赖:不需要泛型
const len = (s: string): number => s.length;

// 返回值依赖参数:加一个类型参数
const uniq = <T,>(arr: T[]): T[] => [...new Set(arr)];
uniq([1, 2, 2]); // number[]

// 参数依赖参数
const logRows = <Row,>(rows: Row[], render: (r: Row) => string) => rows.map(render);

body.en:
// no dependency: no generic needed
const len = (s: string): number => s.length;

// return depends on argument: add a type parameter
const uniq = <T,>(arr: T[]): T[] => [...new Set(arr)];
uniq([1, 2, 2]); // number[]

// argument depends on argument
const logRows = <Row,>(rows: Row[], render: (r: Row) => string) => rows.map(render);
